ALTER TABLE incident_revisions ADD COLUMN superseded_at TEXT;
UPDATE incident_revisions SET superseded_at=(SELECT min(n.known_at) FROM incident_revisions n WHERE n.incident_id=incident_revisions.incident_id AND n.version>incident_revisions.version);
CREATE TRIGGER IF NOT EXISTS revisions_supersede AFTER INSERT ON incident_revisions BEGIN
 UPDATE incident_revisions SET superseded_at=NEW.known_at WHERE incident_id=NEW.incident_id AND version<NEW.version AND (superseded_at IS NULL OR superseded_at>NEW.known_at);
 UPDATE incident_revisions SET superseded_at=(SELECT min(known_at) FROM incident_revisions WHERE incident_id=NEW.incident_id AND version>NEW.version) WHERE incident_id=NEW.incident_id AND version=NEW.version AND EXISTS(SELECT 1 FROM incident_revisions WHERE incident_id=NEW.incident_id AND version>NEW.version);
END;
CREATE INDEX IF NOT EXISTS revisions_cell ON incident_revisions(CAST((json_extract(view,'$.location.lat')+90)/10 AS INTEGER)*37+CAST((json_extract(view,'$.location.lon')+180)/10 AS INTEGER),CASE WHEN json_extract(view,'$.current_listing') THEN '9' ELSE coalesce(max(coalesce(json_extract(view,'$.event_start'),json_extract(view,'$.published_at')),coalesce(json_extract(view,'$.expires_at'),coalesce(json_extract(view,'$.event_start'),json_extract(view,'$.published_at')))),'9') END,known_at);
CREATE INDEX IF NOT EXISTS revisions_lasting ON incident_revisions(CAST((json_extract(view,'$.location.lat')+90)/10 AS INTEGER)*37+CAST((json_extract(view,'$.location.lon')+180)/10 AS INTEGER),CASE WHEN json_extract(view,'$.current_listing') THEN '9' ELSE coalesce(max(coalesce(json_extract(view,'$.event_start'),json_extract(view,'$.published_at')),coalesce(json_extract(view,'$.expires_at'),coalesce(json_extract(view,'$.event_start'),json_extract(view,'$.published_at')))),'9') END,known_at) WHERE CASE WHEN json_extract(view,'$.current_listing') THEN '9' ELSE coalesce(max(coalesce(json_extract(view,'$.event_start'),json_extract(view,'$.published_at')),coalesce(json_extract(view,'$.expires_at'),coalesce(json_extract(view,'$.event_start'),json_extract(view,'$.published_at')))),'9') END>strftime('%Y-%m-%dT%H:%M:%fZ',known_at,'+3 days');
CREATE INDEX IF NOT EXISTS revisions_radius ON incident_revisions(json_extract(view,'$.location.radius_km'));
